// For a given string, flip lowercase characters to uppercase and uppercase to lowercase.
// >>> FlipCase('Hello')
// 'hELLO'
func FlipCase(str string) string {
	var result strings.Builder
	for _, r := range str {
		switch {
		case r >= 'a' && r <= 'z':
			result.WriteRune(r - 'a' + 'A')
		case r >= 'A' && r <= 'Z':
			result.WriteRune(r - 'A' + 'a')
		default:
			result.WriteRune(r)
		}
	}
	return result.String()
}
```

**How it works:**

- Iterates over each rune in the input string.
- If the rune is a lowercase letter (`a`–`z`), it converts it to uppercase by subtracting `'a'` and adding `'A'`.
- If the rune is an uppercase letter (`A`–`Z`), it converts it to lowercase by subtracting `'A'` and adding `'a'`.
- Any other character (digits, punctuation, spaces, etc.) is left unchanged.
- `strings.Builder` is used for efficient string concatenation (avoids repeated allocations that would happen with `+=`).

**Example:**
```
FlipCase("Hello, World!") → "hELLO, wORLD!"
FlipCase("12345")         → "12345"
FlipCase("")              → ""
```

